#include <vector>
#include <string>
#include <optional>
class Solution {
public:
    struct Person {int personId; std::string firstName; std::string lastName;};
    struct Address {int addressId; int personId; std::string city; std::string state;};
    struct Row {std::string firstName; std::string lastName; std::optional<std::string> city; std::optional<std::string> state;};
    // SQL equivalent: SELECT p.firstName, p.lastName, a.city, a.state FROM Person p LEFT JOIN Address a ON p.personId = a.personId
    std::vector<Row> combineTables(std::vector<Person> persons, std::vector<Address> addresses) {
        std::vector<Row> res;
        for (auto &p : persons) {
            bool found = false;
            for (auto &a : addresses) {
                if (a.personId == p.personId) {
                    res.push_back({p.firstName, p.lastName, a.city, a.state});
                    found = true;
                    break;
                }
            }
            if (!found) res.push_back({p.firstName, p.lastName, std::nullopt, std::nullopt});
        }
        return res;
    }
};

