    public List<Row> combineTables(List<Person> persons, List<Address> addresses) {
        List<Row> res = new ArrayList<>();
        for (Person p : persons) {
            boolean found = false;
            for (Address a : addresses) {
                if (a.personId == p.personId) {
                    res.add(new Row(p.firstName, p.lastName, a.city, a.state));
