#include <vector>
#include <string>
#include <optional>
#include <unordered_map>
class Solution {
public:
    struct Person {int personId; std::string firstName; std::string lastName;};
    struct Address {int addressId; int personId; std::string city; std::string state;};
    struct Row {std::string firstName; std::string lastName; std::optional<std::string> city; std::optional<std::string> state;};
    // SQL optimal: SELECT p.firstName, p.lastName, a.city, a.state FROM Person p LEFT JOIN Address a ON p.personId = a.personId
    std::vector<Row> combineTables(std::vector<Person> persons, std::vector<Address> addresses) {
        std::unordered_map<int, Address> mp;
        for (auto &a : addresses) if (!mp.count(a.personId)) mp[a.personId] = a;
        std::vector<Row> res;
        res.reserve(persons.size());
        for (auto &p : persons) {
            auto it = mp.find(p.personId);
            if (it == mp.end()) res.push_back({p.firstName, p.lastName, std::nullopt, std::nullopt});
            else res.push_back({p.firstName, p.lastName, it->second.city, it->second.state});
        }
        return res;
    }
};

