import java.util.*;
class Solution {
    static class Person {int personId; String firstName; String lastName; Person(int id, String f, String l){personId=id; firstName=f; lastName=l;}}
    static class Address {int addressId; int personId; String city; String state; Address(int aid, int pid, String c, String s){addressId=aid; personId=pid; city=c; state=s;}}
    static class Row {String firstName; String lastName; String city; String state; Row(String f, String l, String c, String s){firstName=f; lastName=l; city=c; state=s;}}
    // SQL optimal: SELECT p.firstName, p.lastName, a.city, a.state FROM Person p LEFT JOIN Address a ON p.personId = a.personId
    public List<Row> combineTables(List<Person> persons, List<Address> addresses) {
        Map<Integer, Address> mp = new HashMap<>();
        for (Address a : addresses) mp.putIfAbsent(a.personId, a);
        List<Row> res = new ArrayList<>();
        for (Person p : persons) {
            Address a = mp.get(p.personId);
            if (a == null) res.add(new Row(p.firstName, p.lastName, null, null));
            else res.add(new Row(p.firstName, p.lastName, a.city, a.state));
        }
        return res;
    }
}
